"""Money helpers. All amounts are Decimal; never pass floats in here."""

from decimal import Decimal

CENT = Decimal("0.01")


def to_money(value) -> Decimal:
    """Parse a user-supplied amount ("12.50", 12, Decimal) into a Decimal."""
    return Decimal(str(value))


def to_cents(amount: Decimal) -> Decimal:
    """Round to 2 decimals."""
    return amount.quantize(CENT)

