from decimal import Decimal

from minibill import Invoice, LineItem, line_total, subtotal, total


def test_line_total_multiplies_quantity():
    assert line_total(LineItem("Kalem", "12.50", 3)) == Decimal("37.50")


def test_subtotal_sums_lines():
    invoice = Invoice(items=[LineItem("A", "10.00", 2), LineItem("B", "5.25")])
    assert subtotal(invoice) == Decimal("25.25")


def test_total_applies_discount_then_tax():
    invoice = Invoice(items=[LineItem("A", "100.00")], discount_rate="0.10", tax_rate="0.20")
    assert total(invoice) == Decimal("108.00")

